export type Pendukung2018GroupKey =
  | "KEUANGAN"
  | "VALIDASI_KEUANGAN"
  | "KEADAAN_KEUANGAN"
  | "MONITORING_PERKARA"
  | "KONTROL_PERKARA"
  | "KINERJA_SIPP"
  | "AKTA_CERAI"
  | "LAPORAN"
  | "EKSTERNAL"
  | "MANUAL_REFERENSI";

export type Pendukung2018ImplementationStatus =
  | "READY_READ_ONLY"
  | "READY_OPERATIONAL"
  | "READY_WITH_DATASOURCE"
  | "READY_WITH_AUTO_REVIEWED_QUERY"
  | "PARTIAL_READ_ONLY"
  | "QUERY_NEEDS_REVIEW"
  | "MANUAL_INPUT_REQUIRED"
  | "MANUAL_INPUT_READY"
  | "EXTERNAL_CONNECTOR_REQUIRED"
  | "EXTERNAL_CONNECTOR_WAITING_CONFIG"
  | "REPORT_TEMPLATE_READY"
  | "REPORT_TEMPLATE_REQUIRED"
  | "SCHEMA_MAPPING_REQUIRED"
  | "FORMULA_CONFIGURATION_REQUIRED"
  | "UNSAFE_LEGACY_QUERY_REJECTED"
  | "MISSING_PERIOD_FILTER"
  | "LEGACY_WRITE_REFERENCE_ONLY"
  | "REFERENCE_ONLY";

export type Pendukung2018QueryPlan = {
  queryKey: string;
  queryName: string;
  sql: string;
  tables: string[];
  columns: string[];
  parameters: Array<{ name: string; label: string; dataType: "text" | "date" | "number"; required: boolean }>;
  securityStatus: "SAFE_READ_ONLY" | "NEEDS_REVIEW";
  executionMode: "READY_MONITORING" | "PENDUKUNG2018_REFERENCE_ONLY";
  reviewStatus: "AUTO_IMPORTED" | "NEEDS_ADMIN_REVIEW";
  confidenceScore: number;
  riskNotes: string;
};

export type Pendukung2018FeatureDefinition = {
  featureKey: string;
  featureCode: string;
  featureName: string;
  groupKey: Pendukung2018GroupKey;
  groupName: string;
  sortOrder: number;
  sourceFiles: string[];
  sourceEvidence: string[];
  implementationStatus: Pendukung2018ImplementationStatus;
  migrationStatus: "AUTO_IMPLEMENTED" | "PARTIAL" | "MANUAL_ONLY" | "REFERENCE_ONLY" | "EXTERNAL_REQUIRED";
  safetyStatus: string;
  reviewStatus: "AUTO_IMPORTED" | "NEEDS_ADMIN_REVIEW";
  relatedQueryKey: string;
  relatedIndicatorKey: string;
  tablesUsed: string[];
  columnsUsed: string[];
  periodType: "HARIAN" | "BULANAN" | "TAHUNAN" | "PERIODE_TANGGAL" | "TRIWULAN" | "MANUAL";
  calculationMode: "QUERY_REGISTRY" | "MANUAL_INPUT" | "EXTERNAL_CONNECTOR" | "REFERENCE_ONLY";
  resultType: "REPORT_DATA" | "ISSUE_LIST" | "SCORE" | "EXPORT_REFERENCE";
  noQueryReason: string;
  requiresManualInput: boolean;
  externalDependency: string;
  uiRoute: string;
  riskNotes: string;
  recommendationTemplate: string;
  query: Pendukung2018QueryPlan | null;
};

