const GROUP_BY_KEY = new Map(PENDUKUNG2018_GROUPS.map((group) => [group.groupKey, group]));

const PERIOD_PARAMETERS = [
  { name: "date_start", label: "Tanggal mulai", dataType: "date" as const, required: true },
  { name: "date_end", label: "Tanggal selesai", dataType: "date" as const, required: true },
];

const YEAR_PARAMETERS = [{ name: "tahun", label: "Tahun", dataType: "number" as const, required: true }];
const READ_ONLY_QUERY_PATTERN = /^\s*(?:WITH\b[\s\S]+?\bSELECT\b|SELECT\b|SHOW\b|DESCRIBE\b|EXPLAIN\b)/i;
const BLOCKED_QUERY_PATTERN = /\b(INSERT|UPDATE|DELETE|DROP|ALTER|TRUNCATE|CREATE|REPLACE|GRANT|REVOKE|CALL|LOAD_FILE|INTO\s+OUTFILE|INTO\s+DUMPFILE)\b/i;

function slugKey(value: string, maxLength = 70) {
  return value
    .toLowerCase()
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .replace(/_+/g, "_")
    .slice(0, maxLength) || "fitur";
}

function featureKey(number: number, name: string) {
  return `P2018_${String(number).padStart(3, "0")}_${slugKey(name, 54).toUpperCase()}`;
}

function indicatorKey(number: number, name: string) {
  return `P2018_FEATURE_${String(number).padStart(3, "0")}_${slugKey(name, 50).toUpperCase()}`;
}

function queryKey(number: number, name: string) {
  return `QRY_PENDUKUNG2018_${String(number).padStart(3, "0")}_${slugKey(name, 48).toUpperCase()}`;
}

function q(input: {
  number: number;
  name: string;
  sql: string;
  tables: string[];
  columns: string[];
  parameters?: Pendukung2018QueryPlan["parameters"];
  securityStatus?: Pendukung2018QueryPlan["securityStatus"];
  confidenceScore?: number;
  riskNotes?: string;
}) {
  const normalizedSql = input.sql.replace(/\s+/g, " ").trim();
  const readOnly = READ_ONLY_QUERY_PATTERN.test(normalizedSql) && !BLOCKED_QUERY_PATTERN.test(normalizedSql);
  const securityStatus = readOnly ? input.securityStatus ?? "SAFE_READ_ONLY" : "NEEDS_REVIEW";
  const reviewStatus = input.securityStatus === "NEEDS_REVIEW" ? "NEEDS_ADMIN_REVIEW" : securityStatus === "SAFE_READ_ONLY" ? "AUTO_IMPORTED" : "NEEDS_ADMIN_REVIEW";
  return {
    queryKey: queryKey(input.number, input.name),
    queryName: `${input.name} - Pendukung2018`,
    sql: normalizedSql,
    tables: input.tables,
    columns: input.columns,
    parameters: input.parameters ?? PERIOD_PARAMETERS,
    securityStatus,
    executionMode: securityStatus === "SAFE_READ_ONLY" ? "READY_MONITORING" : "PENDUKUNG2018_REFERENCE_ONLY",
    reviewStatus,
    confidenceScore: input.confidenceScore ?? (securityStatus === "SAFE_READ_ONLY" ? 78 : 55),
    riskNotes: input.riskNotes ?? "Query kandidat disusun ulang sebagai SELECT read-only dengan parameter periode dan LIMIT.",
  } satisfies Pendukung2018QueryPlan;
}

function financialRows(extraWhere = "", extraColumns = "") {
  return `
    SELECT
      pb.id AS transaksi_id,
      pb.perkara_id,
      p.nomor_perkara,
      pb.tanggal_transaksi,
      pb.uraian,
      pb.jumlah,
      pb.jenis_transaksi,
      pb.kategori_id,
      pb.jenis_biaya_id
      ${extraColumns}
    FROM perkara_biaya pb
    LEFT JOIN perkara p ON p.perkara_id = pb.perkara_id
    WHERE pb.tanggal_transaksi BETWEEN :date_start AND :date_end
      ${extraWhere}
    ORDER BY pb.tanggal_transaksi DESC, pb.id DESC
    LIMIT 500
  `;
}

function financialSummary(extraWhere = "") {
  return `
    SELECT
      COUNT(*) AS denominator,
      COUNT(*) AS numerator,
      100 AS score_percent,
      SUM(CASE WHEN pb.jenis_transaksi = 1 THEN pb.jumlah ELSE 0 END) AS total_masuk,
      SUM(CASE WHEN pb.jenis_transaksi = -1 THEN pb.jumlah ELSE 0 END) AS total_keluar,
      SUM(pb.jumlah) AS total_transaksi
    FROM perkara_biaya pb
    WHERE pb.tanggal_transaksi BETWEEN :date_start AND :date_end
      ${extraWhere}
    LIMIT 1
  `;
}

function caseRows(dateColumn = "p.tanggal_pendaftaran", extraWhere = "") {
  return `
    SELECT
      p.perkara_id,
      p.nomor_perkara,
      p.jenis_perkara_nama,
      p.tanggal_pendaftaran,
      pp.tanggal_putusan
    FROM perkara p
    LEFT JOIN perkara_putusan pp ON pp.perkara_id = p.perkara_id
    WHERE ${dateColumn} BETWEEN :date_start AND :date_end
      ${extraWhere}
    ORDER BY ${dateColumn} DESC, p.nomor_perkara
    LIMIT 500
  `;
}

function issueQuery(sql: string) {
  return sql.replace(/\bSELECT\b/i, "SELECT 1 AS is_problem,");
}

function f(input: {
  number: number;
  name: string;
  groupKey: Pendukung2018GroupKey;
  sourceFiles: string[];
  sourceEvidence: string[];
  query?: Pendukung2018QueryPlan | null;
  implementationStatus?: Pendukung2018ImplementationStatus;
  migrationStatus?: Pendukung2018FeatureDefinition["migrationStatus"];
  safetyStatus?: string;
  periodType?: Pendukung2018FeatureDefinition["periodType"];
  calculationMode?: Pendukung2018FeatureDefinition["calculationMode"];
  resultType?: Pendukung2018FeatureDefinition["resultType"];
  noQueryReason?: string;
  requiresManualInput?: boolean;
  externalDependency?: string;
  riskNotes?: string;
  recommendationTemplate?: string;
}) {
  const group = GROUP_BY_KEY.get(input.groupKey);
  if (!group) throw new Error(`Grup Pendukung2018 tidak dikenal: ${input.groupKey}`);
  const key = featureKey(input.number, input.name);
  const query = input.query ?? null;
  const implementationStatus = input.implementationStatus ?? (query?.securityStatus === "SAFE_READ_ONLY" ? "READY_READ_ONLY" : query ? "QUERY_NEEDS_REVIEW" : "REFERENCE_ONLY");
  const safetyStatus = input.safetyStatus ?? (query?.securityStatus === "SAFE_READ_ONLY" ? "SAFE_READ_ONLY" : query ? "NEEDS_REVIEW" : implementationStatus);
  const migrationStatus = input.migrationStatus ?? (implementationStatus === "READY_READ_ONLY" || implementationStatus === "READY_OPERATIONAL" || implementationStatus === "READY_WITH_DATASOURCE" || implementationStatus === "READY_WITH_AUTO_REVIEWED_QUERY" ? "AUTO_IMPLEMENTED" : implementationStatus === "MANUAL_INPUT_REQUIRED" || implementationStatus === "MANUAL_INPUT_READY" ? "MANUAL_ONLY" : implementationStatus === "EXTERNAL_CONNECTOR_REQUIRED" || implementationStatus === "EXTERNAL_CONNECTOR_WAITING_CONFIG" ? "EXTERNAL_REQUIRED" : "PARTIAL");
  const calculationMode = input.calculationMode ?? (query ? "QUERY_REGISTRY" : implementationStatus === "EXTERNAL_CONNECTOR_REQUIRED" || implementationStatus === "EXTERNAL_CONNECTOR_WAITING_CONFIG" ? "EXTERNAL_CONNECTOR" : implementationStatus === "MANUAL_INPUT_REQUIRED" || implementationStatus === "MANUAL_INPUT_READY" || implementationStatus === "LEGACY_WRITE_REFERENCE_ONLY" ? "MANUAL_INPUT" : "REFERENCE_ONLY");
  return {
    featureKey: key,
    featureCode: `P2018-${String(input.number).padStart(3, "0")}`,
    featureName: input.name,
    groupKey: input.groupKey,
    groupName: group.groupName,
    sortOrder: input.number,
    sourceFiles: input.sourceFiles,
    sourceEvidence: input.sourceEvidence,
    implementationStatus,
    migrationStatus,
    safetyStatus,
    reviewStatus: query?.reviewStatus ?? "NEEDS_ADMIN_REVIEW",
    relatedQueryKey: query?.queryKey ?? "",
    relatedIndicatorKey: indicatorKey(input.number, input.name),
    tablesUsed: query?.tables ?? [],
    columnsUsed: query?.columns ?? [],
    periodType: input.periodType ?? "PERIODE_TANGGAL",
    calculationMode,
    resultType: input.resultType ?? (calculationMode === "QUERY_REGISTRY" ? "REPORT_DATA" : "EXPORT_REFERENCE"),
    noQueryReason: input.noQueryReason ?? (query ? "" : "Belum ada query read-only yang aman; fitur disimpan sebagai referensi/manual."),
    requiresManualInput: Boolean(input.requiresManualInput ?? calculationMode === "MANUAL_INPUT"),
    externalDependency: input.externalDependency ?? "",
    uiRoute: `/aleta-sipp?section=pendukung2018&group=${input.groupKey}&feature=${key}`,
    riskNotes: input.riskNotes ?? "Hanya metadata ALETA yang diubah. Database SIPP tetap read-only lewat query registry.",
    recommendationTemplate: input.recommendationTemplate ?? "Review hasil, parameter periode, dan status query sebelum dipakai operasional.",
    query,
  } satisfies Pendukung2018FeatureDefinition;
}

